\Needspace{6\baselineskip}\begin{thm}[Récurrence arithmétique]\ollabel{thm:dedinfiniteinduction}
Soit $N,s,o$ une algèbre de Dedekind. Pour tout ensemble $X$ :
	\begin{center}
		si $o \in X$ et $(\forall {n} \in N \cap X){s}({n}) \in X$,
		alors $N \subseteq X$.
	\end{center}
\end{thm}
